// ── Core set operations in JavaScript ─────────────────────────
const A = new Set([1, 2, 3, 4, 5]);
const B = new Set([3, 4, 5, 6, 7]);

// Union: everything in A or B
const union = new Set([...A, ...B]);
console.log('A ∪ B:', [...union]); // [1,2,3,4,5,6,7]

// Intersection: elements in both
const intersection = new Set([...A].filter(x => B.has(x)));
console.log('A ∩ B:', [...intersection]); // [3,4,5]

// Difference A \ B: in A but not B
const diff_AB = new Set([...A].filter(x => !B.has(x)));
console.log('A \\ B:', [...diff_AB]); // [1,2]

// Symmetric difference: in exactly one of A or B
const symDiff = new Set(
  [...union].filter(x => !intersection.has(x))
);
console.log('A △ B:', [...symDiff]); // [1,2,6,7]

// Cartesian product: all ordered pairs
function cartesian(setA, setB) {
  const result = [];
  for (const a of setA)
    for (const b of setB)
      result.push([a, b]);
  return result;
}
console.log('A×B (small):',
  cartesian(new Set([1, 2]), new Set(['x', 'y'])));
// [[1,'x'],[1,'y'],[2,'x'],[2,'y']]

// Power set: all subsets — 2^n total
function powerSet(arr) {
  return arr.reduce(
    (subsets, val) =>
      subsets.concat(subsets.map(s => [...s, val])),
    [[]]
  );
}
const ps = powerSet(['a', 'b', 'c']);
console.log('|P({a,b,c})|:', ps.length); // 8 = 2^3
console.log('P({a,b,c}):', ps);
// [[], ['a'], ['b'], ['a','b'], ['c'], ['a','c'], ['b','c'], ['a','b','c']]

// ── Checking function properties ──────────────────────────────

// Injective: no two inputs map to the same output
function isInjective(f, domainArr) {
  const seen = new Set();
  for (const x of domainArr) {
    const fx = f(x);
    if (seen.has(fx)) return false; // collision found
    seen.add(fx);
  }
  return true;
}

// Surjective: every codomain element is reachable
function isSurjective(f, domainArr, codomainArr) {
  const images = new Set(domainArr.map(f));
  return codomainArr.every(b => images.has(b));
}

const domain   = [1, 2, 3];
const codomain = [2, 4, 6];
const fDouble  = x => x * 2; // {1→2, 2→4, 3→6}

console.log('fDouble injective :', isInjective(fDouble, domain));              // true
console.log('fDouble surjective:', isSurjective(fDouble, domain, codomain));   // true
console.log('fDouble bijective :', isInjective(fDouble, domain)
  && isSurjective(fDouble, domain, codomain));                                  // true

// f(x) = x² on {-1, 0, 1} — not injective (f(-1) = f(1) = 1)
const fSquare = x => x * x;
console.log('fSquare injective :', isInjective(fSquare, [-1, 0, 1]));          // false

// f(x) = x on {1,2,3} into {1,2,3,4} — injective but not surjective (4 unreached)
const fId = x => x;
const bigCodomain = [1, 2, 3, 4];
console.log('fId injective :', isInjective(fId, domain));                      // true
console.log('fId surjective:', isSurjective(fId, domain, bigCodomain));        // false

// ── Function composition ──────────────────────────────────────
const compose = (...fns) => x => fns.reduceRight((acc, fn) => fn(acc), x);

const double = x => x * 2;
const addOne = x => x + 1;
const square = x => x * x;

// (square ∘ addOne ∘ double)(3) = square(addOne(double(3)))
//                               = square(addOne(6))
//                               = square(7) = 49
const transform = compose(square, addOne, double);
console.log('transform(3):', transform(3)); // 49

// Verify composition of two bijections is bijective
const fA = x => x + 1;            // bijection ℤ → ℤ
const fB = x => x * 3;            // bijection ℤ → ℤ  (on same codomain)
const composed = compose(fB, fA); // x → (x+1)*3
console.log('composed(4):', composed(4)); // (4+1)*3 = 15

// ── Union-Find: implementing equivalence classes ───────────────
class UnionFind {
  constructor(n) {
    this.parent = Array.from({ length: n }, (_, i) => i);
    this.rank   = new Array(n).fill(0);
    this.count  = n; // number of distinct equivalence classes
  }

  // Find with path compression
  find(x) {
    if (this.parent[x] !== x)
      this.parent[x] = this.find(this.parent[x]); // flatten path
    return this.parent[x];
  }

  // Union by rank
  union(x, y) {
    const rx = this.find(x);
    const ry = this.find(y);
    if (rx === ry) return false; // already in same class

    if (this.rank[rx] < this.rank[ry]) this.parent[rx] = ry;
    else if (this.rank[rx] > this.rank[ry]) this.parent[ry] = rx;
    else { this.parent[ry] = rx; this.rank[rx]++; }

    this.count--;
    return true; // merged two distinct classes
  }

  connected(x, y) { return this.find(x) === this.find(y); }
}

// Detect cycles: adding edge (u,v) creates a cycle if u and v
// are already in the same equivalence class
function hasCycle(n, edges) {
  const uf = new UnionFind(n);
  for (const [u, v] of edges) {
    if (!uf.union(u, v)) return true; // same class → cycle
  }
  return false;
}

console.log(hasCycle(4, [[0,1],[1,2],[2,3]]))        // false — a tree
console.log(hasCycle(4, [[0,1],[1,2],[2,3],[3,0]])); // true  — a cycle

// Model equivalence classes: group nodes 0..6 by mod-3
const uf = new UnionFind(7);
for (let i = 3; i < 7; i++) uf.union(i % 3, i); // union 0 with 3,6; 1 with 4; 2 with 5
console.log('Classes remaining:', uf.count); // 3
